"use strict";function parseFilterParameters(){const e=document.querySelector("form");if(!e)return console.warn("No form found on the page. Returning an empty URLSearchParams object."),new URLSearchParams;const t=new FormData(e),n=new URLSearchParams(t);n.delete("csrfmiddlewaretoken");for(const[o,r]of n.entries())r.trim()===""&&n.delete(o);return n}function cleanAndSubmitForm(e){const t=parseFilterParameters(),o=(e.action||window.location.pathname)+(t.toString()?"?"+t.toString():"");return window.location.href=o,!1}function initFilterFormCleanup(){const e=document.querySelector('form[method="get"]');e&&e.addEventListener("submit",function(t){t.preventDefault(),cleanAndSubmitForm(this)})}document.addEventListener("DOMContentLoaded",initFilterFormCleanup);function lockFilter(){document.querySelectorAll(".submit-filter").forEach(t=>{t.value="Loading...",t.textContent="Loading...",t.disabled=!0})}function lockCustomElements(){}function unlockFilter(){document.querySelectorAll(".submit-filter").forEach(t=>{t.value="Filter",t.textContent="Filter",t.disabled=!1})}function unlockCustomElements(){}function clickedFilterButton(){lockFilter()}
